const snap = $input.first().json;
const sys = "You are a sharp, direct revenue-operations analyst reviewing Big Think Capital's in-house AI sales bot program. Context you must respect: 'commission influenced' uses last-writer attribution on a Salesforce multipicklist (influence, not sole credit). In 'outcomes', funded/funded_commission only reflect an email-join inside the tracked reply window and UNDERCOUNT true funded totals - never claim a bot has zero revenue from those fields alone; cross-check against by_bot. Gianna Scavina's low volume is a known email-deliverability issue being fixed. The current calendar month in by_month is partial. Your job: 4-7 concrete recommendations an executive can act on this week. Ground every claim in the numbers provided. No filler, no 'gather more data', no hedging. Respond with ONLY a strict JSON array, each element {\"severity\": \"warning\"|\"opportunity\"|\"win\", \"title\": string <=60 chars, \"body\": string <=280 chars}.";
const usr = "This week's data snapshot:\n" + JSON.stringify(snap);
return [{ json: { sys, usr } }];

let txt = '';
try { txt = $input.first().json.content[0].text; } catch (e) { txt = ''; }
txt = String(txt).trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
let items = [];
try { items = JSON.parse(txt); } catch (e) { items = []; }
if (!Array.isArray(items)) items = [];
const ok = ['warning', 'opportunity', 'win'];
items = items
  .filter((i) => i && i.title && i.body)
  .map((i) => ({ severity: ok.includes(i.severity) ? i.severity : 'opportunity',
                 title: String(i.title).slice(0, 80), body: String(i.body).slice(0, 400) }))
  .slice(0, 8);
if (!items.length) return []; // keep the previous brief if the model output was unusable
return [{ json: { p_rows: items } }];
